const t={material:{intro:{t:0,b:{t:2,i:[{t:3}],s:"सहेजे गए फ़िलामेंट प्रोफ़ाइल - तापमान, घनत्व, और प्रत्येक जिस अधिकतम वॉल्यूमेट्रिक फ़्लो को बनाए रख सकता है।"}},add:{t:0,b:{t:2,i:[{t:3}],s:"मटीरियल जोड़ें"}},loading:{t:0,b:{t:2,i:[{t:3}],s:"लोड हो रहा है…"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"अभी तक कोई मटीरियल नहीं। अपनी फ़िलामेंट लाइब्रेरी बनाना शुरू करने के लिए एक जोड़ें।"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"संपादित करें"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"हटाएँ"}},save:{t:0,b:{t:2,i:[{t:3}],s:"सहेजें"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"रद्द करें"}},list:{flow:{t:0,b:{t:2,i:[{t:4,k:"v"},{t:3,v:" mm³/s"}]}}},fields:{name:{t:0,b:{t:2,i:[{t:3}],s:"नाम"}},material:{t:0,b:{t:2,i:[{t:3}],s:"प्रकार"}},brand:{t:0,b:{t:2,i:[{t:3}],s:"ब्रांड"}},color:{t:0,b:{t:2,i:[{t:3}],s:"रंग"}},diameter:{t:0,b:{t:2,i:[{t:3}],s:"व्यास (mm)"}},density:{t:0,b:{t:2,i:[{t:3}],s:"घनत्व (g/cm³)"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"अधिकतम वॉल्यूमेट्रिक फ़्लो (mm³/s)"}},nozzleTemp:{t:0,b:{t:2,i:[{t:3}],s:"नोज़ल (°C)"}},bedTemp:{t:0,b:{t:2,i:[{t:3}],s:"बेड (°C)"}},notes:{t:0,b:{t:2,i:[{t:3}],s:"नोट्स"}}},flowCheck:{exceeds:{t:0,b:{t:2,i:[{t:4,k:"hotend"},{t:3,v:" सीमा से अधिक ("},{t:4,k:"flow"},{t:3,v:" > "},{t:4,k:"ceiling"},{t:3,v:" mm³/s)"}]}},within:{t:0,b:{t:2,i:[{t:4,k:"hotend"},{t:3,v:" सीमा से "},{t:4,k:"headroom"},{t:3,v:"% कम"}]}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"गाइड"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Material Brain गाइड"}},close:{t:0,b:{t:2,i:[{t:3}],s:"बंद करें"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Material Brain क्या है?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"आपके फ़िलामेंट की एक लाइब्रेरी। प्रत्येक प्रोफ़ाइल तापमान, घनत्व, और वह अधिकतम वॉल्यूमेट्रिक फ़्लो संग्रहित करती है जिसे फ़िलामेंट बनाए रख सकता है - वे संख्याएँ जिन पर ट्यूनिंग और स्लाइसिंग निर्भर करती हैं।"}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:"फ़्लो बनाम hotend सीमा"}},body:{t:0,b:{t:2,i:[{t:3}],s:"प्रत्येक प्रोफ़ाइल का अधिकतम वॉल्यूमेट्रिक फ़्लो आपके hotend की कैटलॉग सीमा के विरुद्ध क्रॉस-चेक किया जाता है, ताकि hotend जितना पिघला सके उससे अधिक माँगने वाली प्रोफ़ाइल अंडर-एक्सट्रूज़न के रूप में दिखने से पहले ही चिह्नित हो जाए।"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"शब्दावली"}}}},glossary:{volumetricFlow:{term:{t:0,b:{t:2,i:[{t:3}],s:"वॉल्यूमेट्रिक फ़्लो"}},def:{t:0,b:{t:2,i:[{t:3}],s:"hotend प्रति सेकंड कितना प्लास्टिक (mm³) पिघलाता है - तेज़ प्रिंटिंग के लिए असली गति सीमा।"}}},density:{term:{t:0,b:{t:2,i:[{t:3}],s:"घनत्व"}},def:{t:0,b:{t:2,i:[{t:3}],s:"प्रति आयतन फ़िलामेंट का द्रव्यमान (g/cm³); वॉल्यूमेट्रिक फ़्लो को द्रव्यमान दर में बदलने के लिए उपयोग किया जाता है।"}}},ceiling:{term:{t:0,b:{t:2,i:[{t:3}],s:"Hotend सीमा"}},def:{t:0,b:{t:2,i:[{t:3}],s:"हार्डवेयर कैटलॉग से, अधिकतम वॉल्यूमेट्रिक फ़्लो जिसे एक hotend बनाए रख सकता है।"}}}}}}};export{t as default};
